'use strict'

import { SPRITE_TEXT_COLOR_WHITE, SPRITE_TEXT_HEIGHT, TILE_WIDTH } from '../constant'
import textManager from '../service/text-manager'
import clock from '../service/clock'

class Character {
  constructor (name, column, line, x, y, width, height, sprite, text) {
    this.name = name
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.sprite = sprite
    this.text = text
    this.displayedText = ''
    this.enabled = true
  }

  init () {
    this.sprite.start()
    this.enabled = true
  }

  reset () {
    this.sprite.stop()
    this.displayedText = ''
  }

  hasStoppedTalking () {
    return this.displayedText === this.text
  }

  draw (context) {
    this.vanishDrawingCalled = true
    if (!this.enabled) {
      return
    }

    this.sprite.draw(context, this.x, this.y, this.width, this.height)
    textManager.draw(context, this.text, SPRITE_TEXT_COLOR_WHITE, this.x - 4.5 * TILE_WIDTH - TILE_WIDTH / 2, this.y - SPRITE_TEXT_HEIGHT * 3, 11 * TILE_WIDTH, SPRITE_TEXT_HEIGHT * 3, 'middle', this.displayedText.length)
  }

  vanish (timeout) {
    const self = this
    self.displayedText = ''
    const timer = clock.repeat(() => {
      if (self.vanishDrawingCalled) {
        self.enabled = !self.enabled
        self.vanishDrawingCalled = false
      }
    }, 5)
    clock.delay(() => {
      timer.cancel()
      self.enabled = false
    }, timeout)
  }
}

export { Character }
